@Component("storageLocation-handler")
@ProcessingGroup("storageLocation-processing-group")
public class StorageLocationEventHandler {
	
	// core constructor
	StorageLocationEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateStorageLocationEvent
     */
    @EventHandler
    public void handle( CreateStorageLocationEvent event) {
        entityManager.persist(new StorageLocation(event.getStorageLocationId(), event.getCode(), event.getTemperatureControlled(), event.getCapacity(), event.getCapacityUnit(), event.getWarehouse(), event.getParentLocation(), event.getChildLocations(), event.getInventoryItems(), event.getLocationType()));
    }

    /*
     * @param	event UpdateStorageLocationEvent
     */
    @EventHandler
    public StorageLocation handle( UpdateStorageLocationEvent event) {
    	entityManager.merge(new StorageLocation(event.getStorageLocationId(), event.getCode(), event.getTemperatureControlled(), event.getCapacity(), event.getCapacityUnit(), event.getWarehouse(), event.getParentLocation(), event.getChildLocations(), event.getInventoryItems(), event.getLocationType()));
    }
    
    /*
     * @param	event DeleteStorageLocationEvent
     */
    @EventHandler
    public void on( DeleteStorageLocationEvent event) {
    	StorageLocation entity = new StorageLocation();
   
    	// ------------------------------------------
    	// apply the StorageLocationId
    	// ------------------------------------------
    	entity.setStorageLocationId( event.getStorageLocationId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final StorageLocationRepository storageLocationEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(StorageLocationEventHandler.class.getName());

}
